  var lastSig = null;
  var inFlight = { add: false };

  function setStatus(s) { statusEl.textContent = s || ''; }

  function norm(raw) {
    // accept [{id,text,bought}] or {items:[...]}
    var arr = Array.isArray(raw) ? raw : (raw && Array.isArray(raw.items) ? raw.items : []);
