      delete pending[id];
      return refresh();
    }).catch(function (e) {
      if (prev !== null) pending[id] = prev; else delete pending[id];
      cb.checked = !!prev;
      setStatus('Could not save change (' + e.message + ')');
      cb.disabled = false;
    }).then(function () { cb.disabled = false; lastSig = null; });
  }

  form.addEventListener('submit', function (ev) {
    ev.preventDefault();
