      body: JSON.stringify({ text: text })
    }).then(function (r) {
      if (!r.ok) throw new Error('HTTP ' + r.status);
      input.value = '';
      input.focus();
      lastSig = null;
      return refresh();
    }).catch(function (e) { setStatus('Could not add item (' + e.message + ')'); })
      .then(function () { inFlight.add = false; });
  });

